version.transform:
(

  $findCreditAt := function($v){(
    $dateInTimeZone := $momentTz($$.date, undefined, $$.timeZone);
    /* $dateInTimeZone := $moment($$.date); */
    $crrHour := $dateInTimeZone.hour();
    $crrMinute := $dateInTimeZone.minute();

    /* If we're after midnight, we'd need to subtract a day. */
    $offsetToMakeDateBeOnStartOfShift := $crrHour < $v.startHour ? -1 : 0;

    /* If we're before midnight, we'd need to add a day. */
    $offsetToMakeDateBeOnEndOfShift := $crrHour < $v.startHour ? 0 : 1;

    /* If the shift "starts" after it "ends", it bridges midnight. */
    $shiftBridgesMidnight := $v.startHour > $v.endHour;

    /* 
      LMENARD 11-2-22
      Decide which offset to use based on the creditAtStart flag on the shift. 
      If the shift doesn't bridge midnight, we don't need to adjust anything at all.
      I feel like this whole thing could be simpler...
    */
    $offsetToUse := $shiftBridgesMidnight 
      ? $v.creditAtStart ? $offsetToMakeDateBeOnStartOfShift : $offsetToMakeDateBeOnEndOfShift
      : 0;

    $dateInTimeZone.add($offsetToUse, "day").startOf("day").format();

  )};

  $allShifts := $isNilOrEmpty(shifts)? $query({
    "statement": 'query Shift($where:ShiftWhereInput){
      shift(where:$where) {
        edges {
          node {
            id
            name
            startHour
            startMinute
            endHour
            endMinute
            creditAtStart
            timeZone

            monday
            tuesday
            wednesday
            thursday
            friday
            saturday
            sunday
          }
        }
      }
    }
    ',
  "variables":{"where": {"shiftGroups":{"_all":{"shiftGroupId":{"_eq":$coalesce([$$.shiftGroupId,"Default"])}}
  }}}}).shift.edges.node
  :
  shifts;

  $shift := $filter(
    $allShifts,
    function($v){(
      $dateInTimeZone := $momentTz($$.date, undefined, $$.timeZone);
      /* $dateInTimeZone := $moment($$.date); */
      $crrHour := $dateInTimeZone.hour();
      $crrMinute := $dateInTimeZone.minute();
      $dayOfWeek := $dateInTimeZone.format("dddd")~>$lowercase;

      $lookup($v, $dayOfWeek) and
      (
        /* Logic for when the shift starts and ends on the same day*/
        (
          (
            $v.startHour < $v.endHour and
            (
                $v.startHour < $crrHour or
                (
                  $v.startHour = $crrHour and
                  $v.startMinute <= $crrMinute
                )

            ) and
            (
              $v.endHour > $crrHour or
              (
                $v.endHour = $crrHour and
                $v.endMinute > $crrMinute
              )
            )
          )
          or
          /* Logic for when the shift starts and ends on different day*/
          (
            $v.startHour > $v.endHour and
            (

                $v.startHour < $crrHour or
                (
                  $v.startHour = $crrHour and
                  $v.startMinute <= $crrMinute
                ) or
                (
                  $v.endHour > $crrHour or
                  (
                    $v.endHour = $crrHour and
                    $v.endMinute > $crrMinute
                  )
                )
            )

          )
        )
      )
    )}
  );



  $shift~>| $ | { "creditAt": $findCreditAt($) } |

)
